            back[it[1]].push_back(it[0]);
        }
        vector<int> vis(n,0);
        queue<int> q;
        q.push(0);
        while(!q.empty())
        {
            int node=q.front();
            q.pop();
            vis[node]=1;
            for(auto it:adj[node])
            {
